<script setup>
import {ref,computed,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {Button,FeatherIcon} from 'frappe-ui'
import {monthLabel} from './monthLabel'
const RepresentativeCharts=defineAsyncComponent(()=>import('./RepresentativeCharts.vue'))
const props=defineProps({name:String,api:Function,formatAmount:Function,formatDate:Function})
defineEmits(['back'])
const report=ref(null),loading=ref(false),error=ref(''),rows=ref([]),listLoading=ref(false),listError=ref(''),kind=ref('Sales Invoice'),page=ref(0),hasMore=ref(false),drill=ref({})
let alive=true,listToken=0
const columns=computed(()=>[{key:'sales',label:monthLabel(report.value?.start_date,'Sales','Current Month Sales')},{key:'month_credit',label:monthLabel(report.value?.start_date,'Credit','Current Month Credit')},{key:'total_credit',label:'Total Credit'},{key:'balance',label:'Account Balance'}])
const buckets=[{key:'not_due',label:'Not due'},{key:'1_30',label:'1–30 days'},{key:'31_60',label:'31–60 days'},{key:'61_90',label:'61–90 days'},{key:'91_plus',label:'91+ days'},{key:'missing',label:'Missing due date'}]
const kinds=['Sales Order','Sales Invoice','Returns','Payment Entry','Credit','Pending Delivery','Pending Billing']
async function load(){loading.value=true;error.value='';try{const value=await props.api('dashboard_representative',{name:props.name});if(alive)report.value=value}catch(_){if(alive)error.value='This representative dashboard is unavailable with your current access.'}finally{if(alive)loading.value=false}}
async function loadRows(){const token=++listToken;listLoading.value=true;listError.value='';try{const value=await props.api('representative_transactions',{name:props.name,kind:kind.value,start:page.value*25,...drill.value});if(!alive||token!==listToken)return;rows.value=value.available?value.items:null;hasMore.value=value.has_more}catch(_){if(alive&&token===listToken){rows.value=[];listError.value='Could not load transactions.'}}finally{if(alive&&token===listToken)listLoading.value=false}}
function selectKind(value,filters={}){kind.value=value;page.value=0;drill.value=filters;loadRows()}
function credit(entry,bucket=null,period=null){selectKind('Credit',{...(entry?.company?{company:entry.company}:{}),...(entry?.currency?{currency:entry.currency}:{}),...(bucket?{bucket}:{}),...(period?{period}:{})});document.getElementById('representative-transactions')?.scrollIntoView({behavior:'smooth',block:'start'})}
function metricClick(column,entry){if(column==='month_credit'||column==='total_credit')credit(entry,null,column==='month_credit'?'month':null)}
function month(value){return monthLabel(value+'-01','',value).trim()+' '+value.slice(0,4)}
onMounted(()=>{load();loadRows()});onBeforeUnmount(()=>{alive=false;listToken++})
</script>
<template>
<div class="min-h-0 flex-1 overflow-y-auto px-4 py-6 sm:px-6"><div class="mx-auto max-w-6xl space-y-6 min-w-0">
  <div><Button variant="ghost" icon-left="arrow-left" @click="$emit('back')">Dashboard</Button><h1 class="mt-3 break-words text-2xl font-semibold">{{report?.label || 'Product representative'}}</h1><p class="mt-1 text-sm text-gray-500">Sales &amp; collections</p></div>
  <p v-if="loading&&!report" role="status" class="text-sm text-gray-500">Loading dashboard…</p><div v-else-if="error" role="alert" class="text-sm text-gray-600">{{error}} <Button size="sm" @click="load">Retry</Button></div>
  <template v-if="report">
    <div class="grid min-w-0 grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4"><section v-for="column in columns" :key="column.key" class="min-w-0 rounded-lg border border-gray-200 bg-white p-5"><h2 class="font-medium">{{column.label}}</h2><p v-if="report.metrics[column.key]===null" class="mt-3 text-sm text-gray-500">Unavailable with your current access.</p><div v-for="(entry,index) in report.metrics[column.key]||[]" :key="index" class="mt-3" :title="entry.company||undefined"><button v-if="['month_credit','total_credit'].includes(column.key)" type="button" class="text-left text-xl font-semibold tabular-nums hover:underline" @click="metricClick(column.key,entry)"><span v-if="entry.currency" class="mr-1 text-sm font-normal text-gray-500">{{entry.currency}}</span>{{formatAmount(entry.amount)}}</button><span v-else class="text-xl font-semibold tabular-nums"><span v-if="entry.currency" class="mr-1 text-sm font-normal text-gray-500">{{entry.currency}}</span>{{formatAmount(entry.amount)}}</span><p v-if="(report.metrics[column.key]||[]).length>1" class="text-xs text-gray-500">{{entry.company}}</p></div><a v-if="column.key==='balance'&&report.account" :href="report.account.url" class="mt-3 block text-sm text-blue-600 hover:underline">Open linked account</a></section></div>
    <section class="rounded-lg border border-gray-200 bg-white p-5 min-w-0" aria-labelledby="rep-trend"><h2 id="rep-trend" class="font-semibold">12-month net sales</h2><p class="mt-1 text-xs text-gray-500">Current month through {{formatDate(report.date)}}; net of returns, excluding opening invoices.</p><p v-if="report.trend===null" class="mt-4 text-sm text-gray-500">Unavailable with your current access.</p><div v-for="series in report.trend||[]" :key="series.company" class="mt-4"><h3 class="text-sm text-gray-600">{{series.currency}}<span v-if="report.trend.length>1"> · {{series.company}}</span></h3><RepresentativeCharts kind="sales" :series="series" :format-amount="formatAmount"/><details class="mt-2 text-sm"><summary class="cursor-pointer text-gray-600">Monthly values</summary><table class="mt-2 w-full text-sm"><thead><tr><th scope="col">Month</th><th scope="col">Net sales</th></tr></thead><tbody><tr v-for="point in series.points" :key="point.month"><th scope="row" class="w-24 py-1 text-left font-normal text-gray-600">{{month(point.month)}}</th><td class="py-1 text-right tabular-nums">{{formatAmount(point.amount)}}</td></tr></tbody></table></details></div></section>
    <section class="rounded-lg border border-gray-200 bg-white overflow-hidden" aria-labelledby="rep-ageing"><div class="px-5 py-4"><h2 id="rep-ageing" class="font-semibold">Outstanding ageing</h2><p class="mt-1 text-xs text-gray-500">Positive non-return invoice balances by due date. Select an amount to view invoices.</p></div><p v-if="report.ageing===null" class="px-5 pb-4 text-sm text-gray-500">Unavailable with your current access.</p><p v-else-if="!report.ageing.length" class="px-5 pb-4 text-sm text-gray-500">No outstanding invoices.</p><template v-else><div v-for="group in report.ageing" :key="group.company+group.currency" class="px-5 pb-4"><h3 class="text-sm text-gray-600">{{group.currency}}<span v-if="report.ageing.length>1"> · {{group.company}}</span></h3><RepresentativeCharts kind="ageing" :series="group" :buckets="buckets" :format-amount="formatAmount" @select="bucket=>credit(group,bucket)"/></div><details class="px-5 pb-4 text-sm"><summary class="cursor-pointer text-gray-600">Amounts and invoice links</summary><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-50"><tr><th scope="col" class="px-5 py-3 text-left font-medium">Currency</th><th v-for="bucket in buckets" :key="bucket.key" scope="col" class="px-4 py-3 text-right font-medium whitespace-nowrap">{{bucket.label}}</th></tr></thead><tbody><tr v-for="group in report.ageing" :key="group.company+group.currency"><th scope="row" class="px-5 py-3 text-left font-normal" :title="group.company">{{group.currency}}<span v-if="report.ageing.length>1" class="block text-xs text-gray-500">{{group.company}}</span></th><td v-for="bucket in buckets" :key="bucket.key" class="px-4 py-3 text-right tabular-nums"><button class="hover:underline" :title="group.buckets[bucket.key].count+' invoices'" @click="credit(group,bucket.key)">{{formatAmount(group.buckets[bucket.key].amount)}}</button></td></tr></tbody></table></div></details></template></section>
    <section class="rounded-lg border border-gray-200 bg-white p-5"><h2 class="font-semibold">Open pipeline</h2><div class="mt-4 grid grid-cols-1 gap-4 sm:grid-cols-3"><div v-for="item in [{key:'delivery',label:'Pending delivery',kind:'Pending Delivery'},{key:'billing',label:'Pending billing',kind:'Pending Billing'},{key:'unpaid',label:'Unpaid invoices',kind:'Credit'}]" :key="item.key"><h3 class="text-sm text-gray-600">{{item.label}}</h3><p v-if="report.pipeline[item.key]===null" class="mt-1 text-sm text-gray-500">Unavailable</p><button v-else class="mt-1 text-2xl font-semibold tabular-nums hover:underline" @click="selectKind(item.kind)">{{report.pipeline[item.key]}}</button></div></div></section>
    <section id="representative-transactions" class="rounded-lg border border-gray-200 bg-white overflow-hidden" aria-labelledby="rep-transactions"><div class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><h2 id="rep-transactions" class="font-semibold">Recent transactions</h2><select :value="kind" class="rounded border border-gray-300 bg-white px-3 py-1 text-sm" aria-label="Transaction type" @change="selectKind($event.target.value)"><option v-for="value in kinds" :key="value">{{value}}</option></select></div><p v-if="kind==='Payment Entry'" class="px-5 pb-3 text-xs text-gray-500">Directly linked Customer receipts (Receive). Amount is the document paid amount, not an invoice allocation or attributed collection total.</p><p v-if="Object.keys(drill).length" class="px-5 pb-3 text-xs text-gray-600">Filtered {{drill.period==='month'?'to current month':''}} {{drill.currency||''}} {{drill.bucket?buckets.find(value=>value.key===drill.bucket)?.label:''}} <button class="ml-2 underline" @click="selectKind(kind)">Clear</button></p><p v-if="listLoading" role="status" class="px-5 pb-4 text-sm text-gray-500">Loading transactions…</p><p v-else-if="listError" role="alert" class="px-5 pb-4 text-sm text-gray-600">{{listError}} <Button size="sm" @click="loadRows">Retry</Button></p><p v-else-if="rows===null" class="px-5 pb-4 text-sm text-gray-500">Unavailable with your current access.</p><p v-else-if="!rows.length" class="px-5 pb-4 text-sm text-gray-500">No matching transactions.</p><div v-else class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-50"><tr><th scope="col" class="px-5 py-3 text-left font-medium">Document</th><th scope="col" class="px-4 py-3 text-left font-medium">Customer / party</th><th scope="col" class="px-4 py-3 text-left font-medium">Date</th><th scope="col" class="px-4 py-3 text-left font-medium">Status</th><th scope="col" class="px-4 py-3 text-right font-medium">{{kind==='Credit'?'Outstanding':'Document amount'}}</th><th v-if="['Sales Invoice','Returns'].includes(kind)" scope="col" class="px-4 py-3 text-right font-medium">Outstanding</th></tr></thead><tbody class="divide-y divide-gray-100"><tr v-for="row in rows" :key="row.name"><td class="px-5 py-3"><a :href="row.url" class="text-blue-600 hover:underline whitespace-nowrap">{{row.name}}</a></td><td class="px-4 py-3 whitespace-nowrap">{{row.party}}</td><td class="px-4 py-3 whitespace-nowrap">{{formatDate(row.date)}}</td><td class="px-4 py-3 whitespace-nowrap">{{row.status}}</td><td class="px-4 py-3 text-right tabular-nums whitespace-nowrap"><template v-if="row.amount!==null"><span class="mr-1 text-xs text-gray-500">{{row.currency}}</span>{{formatAmount(row.amount)}}</template></td><td v-if="['Sales Invoice','Returns'].includes(kind)" class="px-4 py-3 text-right tabular-nums whitespace-nowrap"><template v-if="row.outstanding!==null"><span class="mr-1 text-xs text-gray-500">{{row.outstanding_currency}}</span>{{formatAmount(row.outstanding)}}</template></td></tr></tbody></table></div><div class="flex justify-end gap-2 px-5 py-3"><Button size="sm" :disabled="page===0||listLoading" @click="page--;loadRows()">Previous</Button><Button size="sm" :disabled="!hasMore||listLoading" @click="page++;loadRows()">Next</Button></div></section>
  </template>
</div></div>
</template>
